import cv2from collections import defaultdictfrom src.modules.Speed_tracking import speed_trackingfrom src.modules.Direction import directionleft_side_car = set()counter_car = set()dict_cars_speed = defaultdict(list)dict_cars_direction = defaultdict(list)def tracking(frame, model, start_line, a_start_line, cadr_time=4, s=2.7):    results = model.track(        frame,        persist=True,        tracker="model/botsort.yaml",        imgsz=1280,        classes=[2],        conf=0.25,        verbose=False    )[0]    # если в кадре вообще нет подтверждённых треков — просто отдаём кадр как есть    if results.boxes.id is None:        return frame    global dict_cars_speed    boxes = results.boxes.xyxy.cpu().tolist()    track_ids = results.boxes.id.int().cpu().tolist()    confidences = results.boxes.conf.cpu().tolist()    v_km_s = 0    for box, track_id, confidence in zip(boxes, track_ids, confidences):        xmin, ymin, xmax, ymax = map(int, box)        x = int(xmin)        y = int(ymin)        width = int(xmax - xmin)        height = int(ymax - ymin)        cen_car = ((xmin + xmax) / 2, ymin)        direction(track_id,xmin,ymax,ymin,frame,dict_cars_direction)        speed_tracking(v_km_s,track_id,cen_car,start_line,left_side_car,a_start_line,dict_cars_speed,counter_car,cadr_time,s,frame,x,y)        cv2.putText(frame, str(int(confidence*100))+'%', (x + 100, y), cv2.FONT_HERSHEY_SIMPLEX, 2, (255, 0, 255), 2)        cv2.rectangle(frame, (x, y), (x + width, y + height), (0, 255, 0), 2)        cv2.putText(frame, str(track_id), (x, y), cv2.FONT_HERSHEY_SIMPLEX, 2, (0, 0, 255), 2)        #track_id,direction,crossing_time,t_A,t_B,delta_t,distance_m,speed_km_h    return frame